@once
    @push('styles')
        <style>
            .catalog-quick-filter{margin-top:18px}.catalog-quick-filter__inner{box-sizing:border-box;min-width:0;max-width:100%;padding:18px 22px;border:1px solid var(--line);border-radius:18px;background:var(--white)}.catalog-quick-filter__heading{display:flex;align-items:baseline;gap:10px;margin-bottom:12px}.catalog-quick-filter__heading strong{font-size:16px}.catalog-quick-filter__heading span{color:var(--text-2);font-size:12px}.catalog-quick-filter__items{display:flex;max-width:100%;align-items:center;gap:8px;overflow-x:auto;padding:1px 0 4px;scrollbar-width:thin}.catalog-quick-filter__label{flex:0 0 auto;margin-right:3px;font-weight:650}.catalog-quick-filter__item{display:inline-flex;flex:0 0 auto;align-items:center;gap:7px;padding:8px 12px;border:1px solid var(--line);border-radius:999px;background:var(--white);color:var(--text);transition:.2s}.catalog-quick-filter__item:hover,.catalog-quick-filter__item.is-active{border-color:var(--text);background:var(--text);color:var(--white)}.catalog-quick-filter__prefix{color:var(--text-2);font-size:11px}.catalog-quick-filter__item.is-active .catalog-quick-filter__prefix{color:var(--white-60)}.catalog-quick-filter__count{display:inline-grid;place-items:center;min-width:20px;height:20px;padding:0 5px;border-radius:999px;background:var(--bg);color:var(--text-2);font-size:10px}.catalog-quick-filter__item.is-active .catalog-quick-filter__count{background:var(--white-20);color:var(--white)}@media(max-width:767px){.catalog-quick-filter{margin-top:14px}.catalog-quick-filter__inner{padding:16px 0 13px;border-right:0;border-left:0;border-radius:0}.catalog-quick-filter__heading{align-items:flex-start;flex-direction:column;gap:2px;padding:0 15px}.catalog-quick-filter__items{padding-right:15px;padding-left:15px}.catalog-quick-filter__label{display:none}}
        </style>
    @endpush
@endonce
